import math

def control(obs):
    m=obs['local_map']
    def at(points, x):
        pts=sorted((p[0],p[1]) for p in points if p[0]>-0.5)
        if not pts: return None
        for a,b in zip(pts,pts[1:]):
            if a[0]<=x<=b[0] and b[0]-a[0]<1.0:
                f=(x-a[0])/(b[0]-a[0])
                return a[1]+f*(b[1]-a[1])
        return min(pts,key=lambda p:abs(p[0]-x))[1]
    l=at(m.get('left_rail',[]),2.0)
    r=at(m.get('right_rail',[]),2.0)
    if l is None or r is None:
        return (max(-35,min(35,2.0*obs['hitch_deg'])), -0.3, 180)
    center=(l+r)/2
    desired=max(-22,min(22,math.degrees(math.atan2(center,2.0))*0.8))
    steer=max(-40,min(40,2.2*(obs['hitch_deg']-desired)))
    return (steer,-0.45,180)

